public Yaf_LoaderfalsenullYaf_Loader::registerLocalNamespace string|arraynamespace stringpathnull
注册本地命名空间。前缀属于本地命名空间的类，将在给定的路径下查找（未指定路径时为本地库目录），而不是全局库目录。 这样，你就可以把自己的类放在本地库目录中，而共享类则存放在全局库目录中（参见 yaf.library ini 配置项）。

  &reftitle.examples;

   Yaf_Loader::registerLocalNamespace 示例


<?php
class Bootstrap extends Yaf_Bootstrap_Abstract
{
    public function _initLoader()
    {
        $loader = Yaf_Loader::getInstance();

        /* Models_User 现在将在
         * APPLICATION_PATH/library/Models/User.php 中查找 */
        $loader->registerLocalNamespace("Models");

        /* 一次注册多个前缀，每个都有自己的查找目录 */
        $loader->registerLocalNamespace(array(
            "Services" => APPLICATION_PATH . "/services",
            "Vendor"   => APPLICATION_PATH . "/vendor",
        ));
    }
}
?>
